import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.ChlVJx0I.js";const p=JSON.parse('{"title":"Skill command extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/skill-command.md","filePath":"extensions/skill-command.md","lastUpdated":1791379912000}'),s={name:"extensions/skill-command.md"};function i(r,e,l,d,h,m){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="skill-command-extension" tabindex="-1">Skill command extension <a class="header-anchor" href="#skill-command-extension" aria-label="Permalink to &quot;Skill command extension&quot;">​</a></h1><p>Makes pi recognize a skill command whose name and arguments are separated by a newline, instead of only a space.</p><p>pi expands <code>/skill:name args</code> by parsing the name up to the first space. An injected command whose name and arguments sit on separate lines - the shape the software factory&#39;s consultation templates use, where the command is the first line and the body below it - therefore fails the lookup: the parsed &quot;name&quot; is the name plus the newlines plus the start of the argument text, nothing matches, and the text passes through unexpanded. The model then sees a literal <code>/skill:</code> line and, for skills that carry <code>disable-model-invocation: true</code> (absent from the prompt&#39;s skills section), no pointer to the file at all.</p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li>On every submitted prompt, the extension checks the text. When it starts with <code>/skill:name</code> and the whitespace between the name and the arguments contains a newline, that separator becomes a single space. The arguments keep their remaining bytes; pi trims them when it expands, so the recorded message is what a space-separated command would have produced.</li><li>pi&#39;s built-in expansion runs on the normalized text. The lookup, the SKILL.md read, the frontmatter strip, and the recorded <code>&lt;skill name=... location=...&gt;</code> block are all pi&#39;s; the extension never reads a SKILL.md and adds no setting.</li><li>Commands pi already parses (space separator, bare name) and all non-skill text pass through untouched. An unknown skill name with a newline separator is normalized but still fails pi&#39;s lookup and passes through, as before.</li><li>A tab-only separator is out of scope: pi does not claim that shape either, and no producer injects it.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>The rewrite is one pure function in the engine-free core module (<code>extensions/skill-command/core.ts</code>); the pi wiring (<code>index.ts</code>) registers a single handler on the input event, which fires on every submitted prompt before pi&#39;s own skill and template expansion. See <a href="/pi-extensions/adr/0033-skill-command-normalizes-the-injected-skill-command-separator.html">ADR 0033</a>.</p><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><p>If pi changes how it expands skill commands - for example to accept newline separators natively - the rewrite becomes invisible: it produces the form pi parses today, which a more tolerant pi still parses. If pi changes the <code>/skill:</code> invocation syntax, the regex in the core module needs to follow.</p>',9)])])}const u=t(s,[["render",i]]);export{p as __pageData,u as default};
